/// <summary>
/// Data contract class for sales picking list generation service
/// </summary>
[DataContractAttribute]
class METSalesPickingListGenerationContract
{
    container       salesOrderList;

}

Method.Source:
    /// <summary>
    /// parm method for sales order list container which contains sales order and OSCCode list
    /// </summary>
    /// <param name = "_salesOrderList">sales order list</param>
    /// <returns>sales order list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmSalesOrderList(container _salesOrderList = salesOrderList)
    {
        salesOrderList = _salesOrderList;

        return salesOrderList;
    }
